set -u
echo "E5WRAP start $(date -u +%FT%TZ) gpu=$(nvidia-smi --query-gpu=name --format=csv,noheader 2>/dev/null) cpus=$(nproc)"
mkdir -p /root/e5
# spire-engine's training code needs Python >= 3.12 (f-string with a backslash in training/live_chart.py:430); the image has 3.11
pip install -q uv 2>&1 | tail -1
uv venv -q -p 3.12 /root/e5/venv 2>&1 | tail -2
uv pip install -q --python /root/e5/venv/bin/python torch==2.5.1 --index-url https://download.pytorch.org/whl/cu124 2>&1 | tail -2
uv pip install -q --python /root/e5/venv/bin/python numpy safetensors 2>&1 | tail -2
/root/e5/venv/bin/python -c "import sys, torch; print('E5WRAP venv', sys.version.split()[0], torch.__version__, torch.cuda.is_available())"
echo '' | base64 -d | gunzip > /root/e5_bootstrap.sh
export E5_PHASES="setup build e5b_speed e5b_curve pack" E5B_SPEED_UPDATES=4 E5B_CURVE_UPDATES=100 E5B_CURVE_TIMEOUT=2h
bash /root/e5_bootstrap.sh > /root/e5.log 2>&1
echo "E5WRAP results begin"; grep '^E5RESULT' /root/e5.log
for f in /root/e5/results/train_*.log; do echo "E5WRAP LOG $f"; tail -30 "$f"; done
echo "E5WRAP summary end $(date -u +%FT%TZ)"
sleep 900
